int[] items = { 17, 22, 41, 0 };
int count = 3;
int remove = 1;
int shifts = 0;
if (remove >= 0 && remove < count)
{
    for (int i = remove; i < count - 1; i++)
    {
        items[i] = items[i + 1];
        shifts++;
    }
    count--;
}
for (int i = 0; i < count; i++)
{
    Console.WriteLine(items[i]);
}
Console.WriteLine(shifts);

