int[] queue = { 10, 22, 35, 0 };
int head = 1;
int count = 2;
int reads = 0;
if (count > 0)
{
    int served = queue[head];
    head = (head + 1) % queue.Length;
    count--;
    reads++;
    Console.WriteLine(served);
}
else
{
    Console.WriteLine("فارغ");
}
Console.WriteLine(head);
Console.WriteLine(reads);

